using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using Bokumyaku.Presentation;
public static class MenuScrollCheck {
public static object Run(){var game=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(!game.SavePath.Contains("ink-qa-menu-"))throw new Exception("QA save required");game.SetPage(BokumyakuGame.GamePage.Research);var hud=UnityEngine.Object.FindFirstObjectByType<BokumyakuMenuHud>();hud.Refresh();Canvas.ForceUpdateCanvases();var scroll=hud.GetComponentsInChildren<ScrollRect>().Single();var bar=scroll.verticalScrollbar;if(!bar.gameObject.activeInHierarchy)throw new Exception("Missing scrollbar");var before=scroll.verticalNormalizedPosition;var pos=RectTransformUtility.WorldToScreenPoint(null,scroll.viewport.position);var e=new PointerEventData(EventSystem.current){position=pos,scrollDelta=new Vector2(0,-20)};ExecuteEvents.Execute(scroll.gameObject,e,ExecuteEvents.scrollHandler);Canvas.ForceUpdateCanvases();var after=scroll.verticalNormalizedPosition;if(after>=before)throw new Exception("Scroll input did not move content");var button=scroll.GetComponentsInChildren<Button>().Single(b=>b.name=="MenuResearch3");var corners=new Vector3[4];((RectTransform)button.transform).GetWorldCorners(corners);bool visible=corners[0].y>=scroll.viewport.TransformPoint(scroll.viewport.rect.min).y;if(!visible)throw new Exception("Fourth research not reached");var result=new{width=Screen.width,height=Screen.height,before,after,visible,barSize=bar.size,passed=true};File.WriteAllText(Path.GetFullPath("../docs/evidence/menu-scroll-check.json"),Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));ScreenCapture.CaptureScreenshot(Path.GetFullPath("../docs/evidence/menu-scroll-research.png"));return result;}}
